    {"id": "INSELRAT:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen.","beispiel": "Nach dem Strecken konnte Luis der nächsten Erklärung wieder folgen.","einwaende": [{"id": "INSELRAT_E:lernpause:1","wer": "Grimbart","datei": "zwerg-11-grimbart","einwand": "Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","optionen": [{"text": "Ein klares Endzeichen zeigt, wann wir wieder an der Aufgabe arbeiten.","ok": true,"info": "Die Antwort schlägt eine Lösung für die genannte Sorge vor.","warum": [{"text": "Die Antwort geht auf diese Sorge ein: Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","ok": true},{"text": "Die Antwort geht auf diese Sorge ein: Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen.","ok": false},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false}]},{"text": "Wir wählen sichere Bewegungen mit genug Platz am eigenen Sitz.","ok": false,"info": "Das hilft bei einem anderen Problem, aber nicht bei dieser Sorge."},{"text": "Wir lassen die Kinder kurze Übungen für die Pause vorschlagen.","ok": false,"info": "Das ist ein anderer Vorschlag. Die genannte Sorge bleibt offen."}]},{"id": "INSELRAT_E:lernpause:2","wer": "Amara","datei": "zwerg-10-amara","einwand": "Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen.","optionen": [{"text": "Wir wählen sichere Bewegungen mit genug Platz am eigenen Sitz.","ok": true,"info": "Die Antwort schlägt eine Lösung für die genannte Sorge vor.","warum": [{"text": "Die Antwort geht auf diese Sorge ein: Bei Bewegung im Raum könnten Kinder an Tischkanten stoßen.","ok": true},{"text": "Die Antwort geht auf diese Sorge ein: Nach einer Pause finden manche Kinder schwer zurück zur Aufgabe.","ok": false},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false}]},{"text": "Ein klares Endzeichen zeigt, wann wir wieder an der Aufgabe arbeiten.","ok": false,"info": "Das hilft bei einem anderen Problem, aber nicht bei dieser Sorge."},{"text": "Wir besprechen, bei welchen Aufgaben eine Pause nötig wird.","ok": false,"info": "Das ist ein anderer Vorschlag. Die genannte Sorge bleibt offen."}]}]}
